def score(x):
    """Return predicted minutes remaining for feature vector x (list of 17 floats)."""
    total = _INIT
    unpack = struct.unpack_from
    for start, count in _OFFSETS:
        node = 0
        while True:
            off = start + node * _NS
            feat, thresh, left, right, val = unpack(_FMT, _DATA, off)
            if left == -1:  # leaf
                total += _LR * val
                break
            node = left if x[feat] <= thresh else right
    return total
